import java.util.*;

public class Main {
    static class Edge {
        int y, cap, flow, cost;
        Edge(int y, int cap, int flow, int cost) {
            this.y = y;
            this.cap = cap;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static List<Edge> graphEdges = new ArrayList<>();
    static final int MAXN = 14043;
    static List<Integer>[] adj = new ArrayList[MAXN];

    static long totalFlowCost = 0;
    static long[] dist = new long[MAXN];
    static int[] parentNode = new int[MAXN];
    static int[] parentEdgeIdx = new int[MAXN];
    static int[] inQueue = new int[MAXN];

    static final long INF = (long)1e18;
    static int s = MAXN - 2;
    static int t = MAXN - 1;

    static {
        for (int i = 0; i < MAXN; i++) {
            adj[i] = new ArrayList<>();
        }
    }

    static int residual(int idx) {
        return graphEdges.get(idx).cap - graphEdges.get(idx).flow;
    }

    static void findAugmentingPath() {
        Arrays.fill(dist, INF);
        Arrays.fill(parentNode, -1);
        Arrays.fill(parentEdgeIdx, -1);
        Arrays.fill(inQueue, 0);
        dist[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        inQueue[s] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            inQueue[u] = 0;
            for (int eIdx : adj[u]) {
                if (residual(eIdx) == 0) continue;
                Edge e = graphEdges.get(eIdx);
                int y = e.y;
                int cst = e.cost;
                if (dist[y] > dist[u] + cst) {
                    dist[y] = dist[u] + cst;
                    parentNode[y] = u;
                    parentEdgeIdx[y] = eIdx;
                    if (inQueue[y] == 0) {
                        inQueue[y] = 1;
                        q.offer(y);
                    }
                }
            }
        }
        int cur = t;
        while (cur != s) {
            int eIdx = parentEdgeIdx[cur];
            graphEdges.get(eIdx).flow++;
            graphEdges.get(eIdx ^ 1).flow--;
            cur = parentNode[cur];
        }
        totalFlowCost += dist[t];
    }

    static void createEdge(int from, int to, int capacity, int cost) {
        adj[from].add(graphEdges.size());
        graphEdges.add(new Edge(to, capacity, 0, cost));
        adj[to].add(graphEdges.size());
        graphEdges.add(new Edge(from, 0, 0, -cost));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt() - 1;
            createEdge(s, x, 1, 0);
        }

        int T = 101;
        for (int i = 0; i < T; i++) {
            createEdge(i * n, t, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt() - 1;
            int y = sc.nextInt() - 1;
            for (int j = 0; j < T - 1; j++) {
                createEdge(x + j * n, y + j * n + n, 1, d * (j * 2 + 1));
            }
            for (int j = 0; j < T - 1; j++) {
                createEdge(y + j * n, x + j * n + n, 1, d * (j * 2 + 1));
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < T - 1; j++) {
                createEdge(i + j * n, i + j * n + n, k, 0);
            }
        }

        for (int i = 0; i < k; i++) {
            findAugmentingPath();
        }

        System.out.println(totalFlowCost);
        sc.close();
    }
}
